import itertools, json

riders = ["R", "S", "T", "Y"]
bikes = ["F", "G", "H", "J"]

solutions = []
for p1 in itertools.permutations(bikes):
    d1 = dict(zip(riders, p1))
    for p2 in itertools.permutations(bikes):
        d2 = dict(zip(riders, p2))
        if any(d1[r] == d2[r] for r in riders):
            continue
        if "F" in (d1["R"], d2["R"]):
            continue
        if "J" in (d1["Y"], d2["Y"]):
            continue
        if "H" not in (d1["T"], d2["T"]):
            continue
        # bike Yuki tests day 1 must be tested by Seamus day 2
        if d2["S"] != d1["Y"]:
            continue
        solutions.append((d1, d2))

# Condition: Theresa tests J on day 1
valid = [(d1, d2) for d1, d2 in solutions if d1["T"] == "J"]

options = {
    "A": lambda d1, d2: d2["R"] == "G",
    "B": lambda d1, d2: d1["S"] == "H",
    "C": lambda d1, d2: d2["Y"] == "H",
    "D": lambda d1, d2: "J" in (d1["S"], d2["S"]),
    "E": lambda d1, d2: "G" in (d1["T"], d2["T"]),
}

possible = [k for k, f in options.items() if any(f(d1, d2) for d1, d2 in valid)]

if len(possible) == 1:
    ans = possible[0]
else:
    ans = "UNSUPPORTED"

print(json.dumps({
    "final_answer": ans,
    "evidence": {
        "num_valid_scenarios": len(valid),
        "possible_options": possible,
    },
}))
